    "market": {"south": "hut", "east": "temple"},
    "temple": {"west": "market"},
}

def go(room, direction):
    return WORLD[room].get(direction, room)

alt:
WORLD = {
    "hut": {"north": "market"},
    "market": {"south": "hut", "east": "temple"},
    "temple": {"west": "market"},
}

def go(room, direction):
    exits = WORLD[room]
    if direction in exits:
        return exits[direction]
    return room
